#!/usr/bin/env bash
# Builds the two local images: the Linux twin of infra/build-image.ps1 and infra/build-stream.ps1.
#
#   bash infra/build-images.sh          # both, which is what a fresh host needs
#   bash infra/build-images.sh hlds     # game server only - the usual case, a plugin or config change
#   bash infra/build-images.sh stream   # capture client only
#
# Every URL and its SHA256 comes from infra/checksums.env, generated by infra/update-checksums.ps1
# and never edited by hand. The file is expanded into --build-arg here instead of being passed as
# --build-arg-file: an older buildx does not know that flag, and the values are the same either way.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
checksums="$root/infra/checksums.env"
target="${1:-all}"

die() { printf 'build-images: %s\n' "$*" >&2; exit 1; }
say() { printf 'build-images: %s\n' "$*"; }

command -v docker >/dev/null 2>&1 || die "docker is not installed"
[ -f "$checksums" ] || die "missing $checksums - run infra/update-checksums.ps1 (needs PowerShell) or copy the file from a machine that has one"

declare -A pin=()
while IFS= read -r line || [ -n "$line" ]; do
  # A checkout with CRLF (the file is generated on Windows) leaves a \r at the end of every value,
  # and a URL with a stray CR in it fails deep inside the build with "unsupported protocol scheme".
  line="${line%$'\r'}"
  case "$line" in ''|'#'*) continue ;; esac
  key="${line%%=*}"
  [[ "$key" =~ ^[A-Za-z0-9_]+$ ]] || continue
  pin["$key"]="${line#*=}"
done < "$checksums"
[ ${#pin[@]} -gt 0 ] || die "no key=value pairs in $checksums"

# BuildKit is what the two Dockerfiles are written against (# syntax=1.7, heredocs, cache mounts).
if docker buildx version >/dev/null 2>&1; then
  build=(docker buildx build)
else
  build=(docker build)
fi

build_hlds() {
  local args=() key
  for key in "${!pin[@]}"; do
    args+=(--build-arg "$key=${pin[$key]}")
  done
  say "building cs16-hlds:local"
  ( cd "$root" && "${build[@]}" -f infra/Dockerfile -t cs16-hlds:local "${args[@]}" . )
}

build_stream() {
  # The capture Dockerfile calls its two archives XASH_*/CS16CLIENT_*, the pinned file names them
  # XASH3D_*. Mapping them here keeps both spellings in one place.
  local mapping=(XASH_URL=XASH3D_URL XASH_SHA256=XASH3D_SHA256
                 CS16CLIENT_URL=CS16CLIENT_URL CS16CLIENT_SHA256=CS16CLIENT_SHA256)
  local args=() pair arg source
  for pair in "${mapping[@]}"; do
    arg="${pair%%=*}"
    source="${pair#*=}"
    [ -n "${pin[$source]:-}" ] || die "$source is missing from infra/checksums.env - run infra/update-checksums.ps1"
    args+=(--build-arg "$arg=${pin[$source]}")
  done
  say "building cs16-stream:local"
  ( cd "$root" && "${build[@]}" -f infra/stream/Dockerfile -t cs16-stream:local "${args[@]}" . )
}

case "$target" in
  all) build_hlds; build_stream ;;
  hlds) build_hlds ;;
  stream) build_stream ;;
  *) die "unknown target '$target' (all|hlds|stream)" ;;
esac

say "done: $(docker image list --format '{{.Repository}}:{{.Tag}}' | grep -E '^cs16-(hlds|stream):local$' | sort | tr '\n' ' ')"
